package org.diy.liferecorder;

import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.Bitmap;
import java.io.*;import java.nio.*;import java.util.*;import org.json.*;

/** Synthetic fixture on a disposable emulator; never reads real recordings. */
final class AudayExperienceTests {
    private static int checks;
    private static void check(boolean value,String label)throws Exception{if(!value)throw new IOException(label);checks++;}
    static int run(Instrumentation runner,Context context,boolean ui)throws Exception{
        checks=0;TimeZone original=TimeZone.getDefault();try{
            TimeZone.setDefault(TimeZone.getTimeZone("Asia/Shanghai"));Calendar date=Calendar.getInstance();date.set(2026,9,23,0,0,0);date.set(Calendar.MILLISECOND,0);long day=date.getTimeInMillis();
            JSONArray rows=new JSONArray().put(audio(day-60000,120000,0,new long[]{30000,90000})).put(audio(day,120000,1,new long[]{10000}));
            DayOverview d=DayOverview.from(rows,day);check(d.recordedMs==120000,"overlapping recordings do not double-count coverage");check(d.marks==2,"cross-midnight markers belong to correct day");check(d.pending==1&&d.recordings==2,"pending transcription count distinguishes received recordings");check(d.hours[0]==120000,"hour bins use clipped coverage");
            check(DayOverview.from(new JSONArray().put(audio(DayOverview.next(day),60000,1,new long[]{})),day).recordings==0,"next-day boundary excluded");
            TimeZone.setDefault(TimeZone.getTimeZone("America/New_York"));date.setTimeZone(TimeZone.getDefault());date.set(2026,2,8,0,0,0);date.set(Calendar.MILLISECOND,0);check(DayOverview.next(date.getTimeInMillis())-date.getTimeInMillis()==23*3600000L,"day boundary handles daylight-saving transition");
        }finally{TimeZone.setDefault(original);}
        if(!ui)return checks;
        AppLanguage.set(context,"zh");try(RecordStore db=new RecordStore(context)){JSONArray previous=db.rows("SELECT id FROM audio WHERE title=?","合成示例 · 产品方案与晚间安排");for(int i=0;i<previous.length();i++)db.forget(previous.getJSONObject(i).getString("id"));}String id=AgentPipelineTests.seedUi(context);
        try(RecordStore db=new RecordStore(context)){
            JSONObject source=db.audio(id);File wav=new File(source.getString("path"));int bytes=120*32000;try(DataOutputStream out=new DataOutputStream(new BufferedOutputStream(new FileOutputStream(wav)))){ByteBuffer header=ByteBuffer.allocate(44).order(ByteOrder.LITTLE_ENDIAN);header.put(new byte[]{'R','I','F','F'}).putInt(bytes+36).put(new byte[]{'W','A','V','E','f','m','t',' '}).putInt(16).putShort((short)1).putShort((short)1).putInt(16000).putInt(32000).putShort((short)2).putShort((short)16).put(new byte[]{'d','a','t','a'}).putInt(bytes);out.write(header.array());byte[] silence=new byte[32000];for(int second=0;second<120;second++)out.write(silence);}
            db.getWritableDatabase().execSQL("UPDATE audio SET duration=120000,bytes=?,sha=?,metadata=? WHERE id=?",new Object[]{wav.length(),org.diy.lifecore.LocalSecurity.hash(wav),new JSONObject().put("markers",new JSONArray().put(new JSONObject().put("offset_ms",7000)).put(new JSONObject().put("offset_ms",70000))).toString(),id});
            db.addCandidate("facts",id,"我希望先完成本地记忆，再整理连续事件。");JSONArray facts=db.rows("SELECT id FROM facts WHERE source=?",id);if(facts.length()>0)db.update("facts",facts.getJSONObject(0).getString("id"),"state","accepted");
        }
        MainActivity home=(MainActivity)runner.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));Thread.sleep(1200);runner.waitForIdleSync();String homeText=text(runner,home.body);capture(runner,context,"home");check(homeText.contains("2 分钟")&&homeText.contains("2 个标记"),"home displays real duration and mark counts");check(!homeText.contains("卵石微呼吸")&&!homeText.contains("此时身表情境"),"home removes unrelated decorative modules");capture(runner,context,"home");
        MainActivity archive=(MainActivity)runner.startActivitySync(new Intent(context,MainActivity.class).putExtra("page","memory").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));Thread.sleep(1000);check(text(runner,archive.body).contains("当天回顾"),"archive exposes selected-day review");capture(runner,context,"archive");
        RecordActivity detail=(RecordActivity)runner.startActivitySync(new Intent(context,RecordActivity.class).putExtra("id",id).putExtra("seek_ms",7000L).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));Thread.sleep(1500);check(text(runner,detail.root).contains("转写")&&text(runner,detail.root).contains("重点")&&text(runner,detail.root).contains("总结"),"detail has three reading tabs");final boolean[] fits={false};runner.runOnMainSync(()->{Button play=find(detail.root,"暂停");if(play==null)play=find(detail.root,"播放");fits[0]=play!=null&&play.getLayout()!=null&&play.getLayout().getLineCount()==1&&play.getLayout().getEllipsisCount(0)==0;});check(fits[0],"playback label remains on one unclipped line at current font size");capture(runner,context,"transcript");runner.runOnMainSync(()->click(detail.body,"重点"));Thread.sleep(300);capture(runner,context,"highlights");runner.runOnMainSync(()->click(detail.body,"总结"));Thread.sleep(300);capture(runner,context,"summary");
        MainActivity memory=(MainActivity)runner.startActivitySync(new Intent(context,MainActivity.class).putExtra("memory_detail",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));Thread.sleep(400);check(text(runner,memory.body).contains("已保存")&&text(runner,memory.body).contains("已停用"),"memory has explicit review states");capture(runner,context,"memory");
        SearchActivity search=(SearchActivity)runner.startActivitySync(new Intent(context,SearchActivity.class).putExtra("query","本地记忆方案").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));Thread.sleep(1600);check(text(runner,search.body).contains("匹配"),"local search produces results without API configuration");capture(runner,context,"search");
        ExportActivity export=(ExportActivity)runner.startActivitySync(new Intent(context,ExportActivity.class).putExtra("source",id).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));Thread.sleep(400);check(text(runner,export.body).contains("原始录音")&&text(runner,export.body).contains("标记重点"),"selective export exposes real content types");capture(runner,context,"export");
        return checks;
    }
    private static JSONObject audio(long at,long duration,int transcribed,long[] marks)throws Exception{JSONArray list=new JSONArray();for(long mark:marks)list.put(new JSONObject().put("offset_ms",mark));return new JSONObject().put("created",at).put("duration",duration).put("transcribed",transcribed).put("metadata",new JSONObject().put("markers",list).toString());}
    private static String text(Instrumentation runner,View view){String[] out={""};runner.runOnMainSync(()->out[0]=words(view));return out[0];}
    private static String words(View view){StringBuilder s=new StringBuilder();if(view.getVisibility()!=View.VISIBLE)return "";if(view instanceof TextView)s.append(((TextView)view).getText()).append('\n');if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)s.append(words(((ViewGroup)view).getChildAt(i)));return s.toString();}
    private static Button find(View view,String label){if(view instanceof Button&&((Button)view).getText().toString().equals(label))return (Button)view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){Button found=find(((ViewGroup)view).getChildAt(i),label);if(found!=null)return found;}return null;}
    private static boolean click(View view,String label){if(view instanceof Button&&((Button)view).getText().toString().equals(label)){view.performClick();return true;}if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)if(click(((ViewGroup)view).getChildAt(i),label))return true;return false;}
    private static void capture(Instrumentation runner,Context context,String name)throws Exception{Bitmap bitmap=runner.getUiAutomation().takeScreenshot();if(bitmap==null)throw new IOException("screenshot unavailable");try(OutputStream out=new FileOutputStream(new File(context.getCacheDir(),"auday-"+name+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}
}
